type PlaceSeed = [name: string, country: string, year: number, longitude: number, latitude: number]
type PersonSeed = [
  wikidataId: string,
  name: string,
  aliases: string[],
  category: string,
  famousWork: string,
  fact: string,
  difficulty: Difficulty,
  birth: PlaceSeed,
  death: PlaceSeed,
]

const place = ([name, country, year, longitude, latitude]: PlaceSeed) => ({
  name, country, year, coordinates: [longitude, latitude] as [number, number],
})

const slug = (name: string) => name
  .normalize('NFD').replace(/\p{Diacritic}/gu, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '')

