const catalogInput: Person[] = seeds.map(([
  wikidataId, name, aliases, category, famousWork, fact, difficulty, birth, death,
]) => ({
  id: slug(name),
  wikidataId,
  name,
  aliases,
  category,
  difficulty,
  birth: place(birth),
  death: place(death),
  hints: [category, famousWork, fact],
  summary: fact,
  sources: [
    { label: 'Wikidata', url: `https://www.wikidata.org/wiki/${wikidataId}` },
  ],
  portrait: portraits[wikidataId],
}))

export const people = validateCatalog(catalogInput)
